<script setup lang="ts">import{Plus,Search}from'@element-plus/icons-vue';import{computed,onMounted,shallowRef}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import RepositoryFormDialog from'@/features/repositories/RepositoryFormDialog.vue';import RepositoryTable from'@/features/repositories/RepositoryTable.vue';import{sourceImportsApi}from'@/api/sourceImports';import{useRepositoryStore}from'@/stores/repositoryStore';const store=useRepositoryStore(),query=shallowRef(''),dialogOpen=shallowRef(false),rescanningId=shallowRef<string|null>(null),importing=shallowRef(false);const rows=computed(()=>{const q=query.value.trim().toLowerCase();return q?store.repositories.filter(x=>`${x.name} ${x.path} ${x.sourceType} ${x.branch??''} ${x.commit??''}`.toLowerCase().includes(q)):store.repositories});type Input={sourceType:'LOCAL_GIT'|'REMOTE_GIT'|'GITLAB'|'ZIP';name:string;path:string;url:string;branch:string;file:File|null};async function create(input:Input){importing.value=true;try{if(input.sourceType==='LOCAL_GIT')await store.createRepository({name:input.name,path:input.path});else if(input.sourceType==='ZIP'){if(!input.file)throw new Error('请选择 ZIP 文件');await sourceImportsApi.zip(input.name,input.file);await store.loadRepositories()}else{await sourceImportsApi.remote({name:input.name,url:input.url,branch:input.branch,sourceType:input.sourceType});await store.loadRepositories()}dialogOpen.value=false;ElMessage.success('仓库快照已验证并发布')}catch(e){ElMessage.error(e instanceof Error?e.message:'导入失败')}finally{importing.value=false}}async function rescan(id:string){rescanningId.value=id;try{const r=await store.rescanRepository(id);ElMessage.success(r.changed?'检测到代码变化，已发布新快照':'代码版本无变化')}finally{rescanningId.value=null}}async function startIndex(id:string){await store.createIndexJob(id,'FULL');ElMessage.success('全量内容索引任务已进入队列')}async function remove(id:string,name:string){await ElMessageBox.confirm(`删除平台中的“${name}”及其派生数据；本地原目录不会被修改。`,'删除仓库',{type:'warning'});await store.removeRepository(id)}onMounted(()=>void store.loadRepositories());</script>
<template><section class="page repository-design"><div class="summary-strip"><div><span>仓库总数</span><b>{{store.repositories.length}}</b></div><div><span>本地 Git</span><b>{{store.repositories.filter(x=>x.sourceType==='LOCAL_GIT').length}}</b></div><div><span>远程/GitLab</span><b>{{store.repositories.filter(x=>['REMOTE_GIT','GITLAB'].includes(x.sourceType)).length}}</b></div><div><span>ZIP</span><b>{{store.repositories.filter(x=>x.sourceType==='ZIP').length}}</b></div></div><div class="surface"><div class="toolbar"><el-input v-model="query" :prefix-icon="Search" placeholder="搜索名称、来源、路径、分支或 commit" clearable/><span class="spacer"/><el-button type="primary" :icon="Plus" :loading="importing" @click="dialogOpen=true">接入仓库</el-button></div><el-alert v-if="store.error" :title="store.error" type="error" :closable="false"/><RepositoryTable :rows="rows" :loading="store.loading" :rescanning-id="rescanningId" @index="startIndex" @rescan="rescan" @remove="remove"/></div><RepositoryFormDialog v-model="dialogOpen" @submit="create"/></section></template>
